    document.body.style.cursor = "col-resize";
    e.preventDefault();
  });
  window.addEventListener("mousemove", (e) => {
    if (!dragging) return;
    const rect = wrap.getBoundingClientRect();
    const min = 300;
    let leftW = Math.max(min, Math.min(rect.width - min - 6, e.clientX - rect.left));
    main.style.flex = "0 0 " + leftW + "px";
    assist.style.flex = "1 1 auto";
  });
  window.addEventListener("mouseup", () => {
    if (!dragging) return;
